package com.vibecode.roadmap.application; import com.vibecode.output.domain.OutputAnalysisStatus; import com.vibecode.task.domain.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class DeterministicNextStepEngine {private final WorkflowService flow;private final ProjectStateService state; public DeterministicNextStepEngine(WorkflowService f,ProjectStateService s){flow=f;state=s;} public WorkflowRecommendation recommend(UUID p){ProjectState s=state.state(p);if(s.totalTasks()==0)return rec(NextStepType.WAIT_FOR_USER,"Estruturar roadmap","O projeto ainda não possui tarefas.",null,"HIGH",com.vibecode.prompt.domain.PromptType.ASK_FOR_EVIDENCE);if(s.completedTasks()==s.totalTasks())return rec(NextStepType.PROJECT_COMPLETE,"Projeto concluído","Todas as tarefas foram concluídas com evidência.",null,"LOW",com.vibecode.prompt.domain.PromptType.MODEL_HANDOFF);WorkflowTask t=s.currentTask();if(t!=null){var a=flow.latest(t.id());if(a.isPresent()){if(a.get().status()==OutputAnalysisStatus.FAILURE||a.get().status()==OutputAnalysisStatus.PARTIAL)return rec(NextStepType.FIX_ERROR,"Corrigir "+t.title(),"A última evidência falhou.",t.id(),"CRITICAL",com.vibecode.prompt.domain.PromptType.FIX_ERROR);if(a.get().status()==OutputAnalysisStatus.BLOCKED)return rec(NextStepType.RESOLVE_BLOCKER,"Resolver bloqueio: "+t.title(),"A última evidência está bloqueada.",t.id(),"CRITICAL",com.vibecode.prompt.domain.PromptType.RESOLVE_BLOCKER);if(a.get().status()==OutputAnalysisStatus.NEEDS_VALIDATION)return rec(NextStepType.VALIDATE_RESULT,"Validar resultado: "+t.title(),"Ainda não há evidência técnica suficiente.",t.id(),"HIGH",com.vibecode.prompt.domain.PromptType.VALIDATE_RESULT);}if(t.status()==WorkflowTaskStatus.IN_PROGRESS)return rec(NextStepType.CONTINUE_TASK,"Continuar "+t.title(),"A tarefa está em progresso.",t.id(),"MEDIUM",com.vibecode.prompt.domain.PromptType.CONTINUE_TASK);}
 WorkflowTask next=s.nextCandidateTasks().stream().findFirst().orElse(null);return next==null?rec(NextStepType.WAIT_FOR_USER,"Resolver dependências","Não há tarefa elegível.",null,"HIGH",com.vibecode.prompt.domain.PromptType.ASK_FOR_EVIDENCE):rec(NextStepType.START_TASK,next.title(),"É a primeira tarefa READY sem dependências pendentes.",next.id(),"MEDIUM",com.vibecode.prompt.domain.PromptType.START_TASK);} private WorkflowRecommendation rec(NextStepType ty,String title,String reason,UUID id,String priority,com.vibecode.prompt.domain.PromptType pt){return new WorkflowRecommendation(ty,title,reason,id,priority,List.of(),List.of(reason),pt);}}
